 const base=act&&(!bs||mkRefD(act)>=bs.from)?{...act,kind:proxy?'proxy':'bank'}:bs?{mode:'sea',...bs,kind:'base'}:null;if(!base)return {lane,o,base:null};const a=mkAdj({mode:'sea',...base},H);const fu=mkAdj({mode:'sea',pol:base.pol,pod:base.pod,amt:1,cur:'USD',from:mkRefD(base)},H);
