function mkWatchVal(w,H=mkHist()){if(w.type==='index'){const l=mkLast(H,w.key);return l?{v:l[1],d:l[0]}:null}const e=mkEstimate({pol:w.pol,pod:w.pod,eq:w.eq},H);return e.base?{v:e.usd,d:fwToday()}:null}
